import SwiftUI

/// The project's articles and design pages, to read in the app (the owner's request: "articles inside
/// the app he can read"). Generated by website/admin/ideas.mjs as vd-articles.json; each is the page's
/// own markdown, with links pointed at the site and pictures named in their place.
struct Article: Codable, Hashable, Identifiable, Sendable {
    let id: String
    let title: String
    let app: String
    let kind: String
    let summary: String
    let markdown: String
    let url: String
}

struct ArticleBook: Codable, Sendable {
    let articles: [Article]

    static let resource = "vd-articles"

    static func bundled(_ bundle: Bundle = .main) -> ArticleBook? {
        guard let url = bundle.url(forResource: resource, withExtension: "json"),
              let data = try? Data(contentsOf: url) else { return nil }
        return try? JSONDecoder().decode(ArticleBook.self, from: data)
    }
}

/// A page of markdown cut into the blocks the articles use, so each can be shown on its own.
enum ArticleBlock: Hashable {
    case heading(level: Int, text: String)
    case paragraph(String)
    case bullet(String)
    case quote(String)
    case code(String)

    static func parse(_ markdown: String) -> [ArticleBlock] {
        var blocks: [ArticleBlock] = []
        var lines = markdown.components(separatedBy: "\n")[...]
        var para: [String] = []
        func flush() {
            if !para.isEmpty { blocks.append(.paragraph(para.joined(separator: " "))); para = [] }
        }
        while let line = lines.popFirst() {
            let t = line.trimmingCharacters(in: .whitespaces)
            if t.hasPrefix("```") {
                flush()
                var code: [String] = []
                while let l = lines.popFirst(), !l.trimmingCharacters(in: .whitespaces).hasPrefix("```") { code.append(l) }
                blocks.append(.code(code.joined(separator: "\n")))
            } else if t.isEmpty {
                flush()
            } else if t.hasPrefix("#") {
                flush()
                let level = t.prefix { $0 == "#" }.count
                blocks.append(.heading(level: level, text: t.dropFirst(level).trimmingCharacters(in: .whitespaces)))
            } else if t.hasPrefix("- ") || t.hasPrefix("* ") {
                flush()
                blocks.append(.bullet(String(t.dropFirst(2))))
            } else if let r = t.range(of: #"^\d+\. "#, options: .regularExpression) {
                flush()
                let number = String(t[t.startIndex..<r.upperBound]).trimmingCharacters(in: .whitespaces)
                let rest = String(t[r.upperBound...])
                blocks.append(.bullet(number + " " + rest))
            } else if t.hasPrefix(">") {
                flush()
                blocks.append(.quote(t.drop { $0 == ">" || $0 == " " }.description))
            } else if t.hasPrefix("|") {
                flush()
                // a table, read as rows of cells; the separator row is dropped
                if t.allSatisfy({ "|-: ".contains($0) }) { continue }
                let cells = t.trimmingCharacters(in: CharacterSet(charactersIn: "|")).components(separatedBy: "|")
                    .map { $0.trimmingCharacters(in: .whitespaces) }.filter { !$0.isEmpty }
                blocks.append(.bullet(cells.joined(separator: " · ")))
            } else {
                para.append(t)
            }
        }
        flush()
        return blocks
    }
}

struct ArticlesView: View {
    let book: ArticleBook
    @State private var query = ""

    private var results: [Article] {
        let words = query.lowercased().split(whereSeparator: \.isWhitespace)
        return book.articles.filter { a in
            words.allSatisfy { (a.title + " " + a.markdown).lowercased().contains($0) }
        }
    }

    var body: some View {
        List(results) { a in
            NavigationLink { ArticleView(article: a) } label: {
                VStack(alignment: .leading, spacing: 4) {
                    Text(a.title).font(.body.weight(.medium))
                    Text(a.kind).font(.caption).foregroundStyle(.secondary)
                    if !a.summary.isEmpty { Text(a.summary).font(.footnote).foregroundStyle(.secondary).lineLimit(3) }
                }
                .padding(.vertical, 2)
            }
        }
        .readableWidth()
        .overlay {
            if results.isEmpty { ContentUnavailableView.search(text: query) }
        }
        .searchable(text: $query, prompt: "Search the articles")
        .navigationTitle("Articles")
    }
}

struct ArticleView: View {
    let article: Article

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 12) {
                Text(article.title).font(.title2.weight(.semibold))
                ForEach(Array(ArticleBlock.parse(article.markdown).enumerated()), id: \.offset) { _, block in
                    view(for: block)
                }
                if let url = URL(string: article.url) {
                    Link(destination: url) { Label("On the project's site, with its pictures", systemImage: "globe") }
                        .padding(.top, 8)
                }
            }
            .frame(maxWidth: 680, alignment: .leading)
            .padding()
            .frame(maxWidth: .infinity)
        }
        .textSelection(.enabled)
        .navigationTitle(article.kind)
        .navigationBarTitleDisplayMode(.inline)
    }

    @ViewBuilder
    private func view(for block: ArticleBlock) -> some View {
        switch block {
        case let .heading(level, text):
            Text(Self.inline(text)).font(level <= 2 ? .title3.weight(.semibold) : .headline).padding(.top, 6)
        case let .paragraph(text):
            Text(Self.inline(text))
        case let .bullet(text):
            HStack(alignment: .firstTextBaseline, spacing: 8) {
                Text("•").foregroundStyle(.secondary)
                Text(Self.inline(text))
            }
        case let .quote(text):
            Text(Self.inline(text)).foregroundStyle(.secondary).padding(.leading, 12)
                .overlay(alignment: .leading) { Rectangle().fill(.secondary.opacity(0.4)).frame(width: 3) }
        case let .code(text):
            ScrollView(.horizontal) { Text(text).font(.system(.footnote, design: .monospaced)) }
                .padding(10).background(.secondary.opacity(0.1), in: RoundedRectangle(cornerRadius: 8))
        }
    }

    static func inline(_ text: String) -> AttributedString {
        (try? AttributedString(markdown: text, options: .init(interpretedSyntax: .inlineOnlyPreservingWhitespace))) ?? AttributedString(text)
    }
}
